import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const OWNED_PREFIX = "./assets/commitatlas/";
const MAX_README_BYTES = 1_000_000;
const MAX_MANIFEST_BYTES = 64 * 1024;
const ARTIFACT_NAME = /^[a-z0-9][a-z0-9.-]{0,63}\.(?:svg|json|md)$/;
const SPACE = /[\t\n\f\r ]/;

/**
 * Run after bundle validation and catalog rendering. The shared bundle validator proves that
 * the manifest hashes describe the generated bytes; this step binds every owned HTML image URL
 * to its artifact's hash, so a refreshed README also changes the image cache key.
 */
export function updateCommitAtlasImageVersions(root = process.cwd()) {
  const readmePath = path.join(root, "README.md");
  const readme = readRegular(readmePath, MAX_README_BYTES, "README");
  const versions = readVersions(root);
  const updated = readme.replace(
    /<!--[\s\S]*?-->|<[a-z][a-z0-9:-]*(?=[\t\n\f\r />])(?:[^<>"']|"[^"]*"|'[^']*')*>/gi,
    (tag) => tag.startsWith("<!--") ? tag : versionTag(tag, versions),
  );
  if (Buffer.byteLength(updated, "utf8") > MAX_README_BYTES) {
    throw new Error("versioned README exceeds the read limit");
  }
  // All manifests and references have been checked before the first write. Retain the original
  // bytes, formatting, and mtime when the current versions are already present.
  if (updated !== readme) fs.writeFileSync(readmePath, updated, "utf8");
  return { changed: updated !== readme };
}

function readVersions(root) {
  const versions = new Map();
  for (const directory of ["assets/commitatlas", "assets/commitatlas/light"]) {
    const label = `${directory}/manifest.json`;
    const raw = readRegular(path.join(root, label), MAX_MANIFEST_BYTES, label);
    let manifest;
    try {
      manifest = JSON.parse(raw);
    } catch (error) {
      throw new Error(`${label} is not valid JSON: ${error.message}`, { cause: error });
    }
    if (!manifest || manifest.version !== 1 || manifest.generator !== "CommitAtlas") {
      throw new Error(`${label} must be a version 1 CommitAtlas manifest`);
    }
    if (!Array.isArray(manifest.artifacts) || manifest.artifacts.length < 1 || manifest.artifacts.length > 96) {
      throw new Error(`${label} must contain a bounded artifacts array`);
    }
    const seen = new Set();
    for (const artifact of manifest.artifacts) {
      if (!artifact || typeof artifact.path !== "string" || !ARTIFACT_NAME.test(artifact.path) || artifact.path.includes("..")) {
        throw new Error(`${label} contains a noncanonical artifact path`);
      }
      if (seen.has(artifact.path)) throw new Error(`${label} contains a duplicate artifact path`);
      seen.add(artifact.path);
      if (typeof artifact.sha256 !== "string" || !/^[a-f0-9]{64}$/.test(artifact.sha256)) {
        throw new Error(`${label} contains an invalid artifact SHA256 hash`);
      }
      if (artifact.path.endsWith(".svg")) {
        versions.set(`./${directory}/${artifact.path}`, artifact.sha256.slice(0, 16));
      }
    }
  }
  return versions;
}

function versionTag(tag, versions) {
  // Match all attributes, including those we leave alone, so an example `src="..."` inside
  // another quoted attribute cannot be mistaken for an image reference.
  return tag.replace(
    /(\s+)([^\s"'<>/=]+)(\s*=\s*)(?:"([^"]*)"|'([^']*)'|([^\s"'<>`]+))/g,
    (attribute, space, name, equals, doubleQuoted, singleQuoted, unquoted) => {
      const kind = name.toLowerCase();
      if (!["src", "srcset", "href"].includes(kind)) return attribute;
      const quote = doubleQuoted !== undefined ? '"' : singleQuoted !== undefined ? "'" : "";
      const value = doubleQuoted ?? singleQuoted ?? unquoted;
      const updated = kind === "srcset"
        ? versionSrcset(value, versions)
        : value.replace(/^([\t\n\f\r ]*)([\s\S]*?)([\t\n\f\r ]*)$/, (_, before, url, after) => `${before}${versionUrl(url, versions)}${after}`);
      return `${space}${name}${equals}${quote}${updated}${quote}`;
    },
  );
}

function versionSrcset(value, versions) {
  let cursor = 0;
  let copied = 0;
  let result = "";
  while (cursor < value.length) {
    while (cursor < value.length && (SPACE.test(value[cursor]) || value[cursor] === ",")) cursor += 1;
    if (cursor === value.length) break;
    const start = cursor;
    // A srcset URL ends at whitespace. Commas within a URL (such as a data URL) are significant;
    // trailing commas separate candidates. Preserve descriptors and separators byte for byte.
    while (cursor < value.length && !SPACE.test(value[cursor])) cursor += 1;
    let end = cursor;
    let descriptor = "";
    if (value[end - 1] === ",") {
      while (value[end - 1] === ",") end -= 1;
    } else {
      const descriptorStart = cursor;
      while (cursor < value.length && value[cursor] !== ",") cursor += 1;
      descriptor = value.slice(descriptorStart, cursor).trim();
    }
    const url = value.slice(start, end);
    const updated = versionUrl(url, versions);
    if (url.startsWith(OWNED_PREFIX) && descriptor && !/^(?:[1-9][0-9]*w|(?:[0-9]+(?:\.[0-9]+)?|\.[0-9]+)x)$/.test(descriptor)) {
      throw new Error("owned image srcset has an ambiguous descriptor");
    }
    result += value.slice(copied, start) + updated;
    copied = end;
  }
  return result + value.slice(copied);
}

function versionUrl(url, versions) {
  if (!url.startsWith(OWNED_PREFIX)) {
    if (url.startsWith("./assets/commitatlas\\")) throw new Error("owned image path must use canonical slashes");
    return url;
  }
  const [, pathname, query, fragment = ""] = /^([^?#]*)(\?[^#]*)?(#[\s\S]*)?$/.exec(url);
  const filename = pathname.slice(OWNED_PREFIX.length).replace(/^light\//, "");
  if (!ARTIFACT_NAME.test(filename) || filename.includes("..")) {
    throw new Error("owned image path must be canonical and may not traverse directories");
  }
  if (!filename.endsWith(".svg")) return url;
  const version = versions.get(pathname);
  if (!version) throw new Error(`unknown owned SVG path: ${pathname}`);
  // Only our single cache-version parameter is owned. Refuse any other spelling or parameter
  // combination instead of guessing how it should be merged, decoded, or discarded.
  if (query !== undefined && !/^\?v=[A-Za-z0-9._-]+$/.test(query)) {
    throw new Error(`owned SVG has an ambiguous query: ${pathname}`);
  }
  if (/[\s"'<>`]/u.test(fragment)) throw new Error(`owned SVG has a noncanonical fragment: ${pathname}`);
  return `${pathname}?v=${version}${fragment}`;
}

function readRegular(filePath, limit, label) {
  const stats = fs.lstatSync(filePath);
  if (!stats.isFile() || stats.nlink !== 1) throw new Error(`${label} must be a regular single-link file`);
  if (stats.size > limit) throw new Error(`${label} exceeds the ${limit}-byte read limit`);
  const bytes = fs.readFileSync(filePath);
  const value = bytes.toString("utf8");
  if (!Buffer.from(value, "utf8").equals(bytes)) throw new Error(`${label} must be valid UTF-8`);
  return value;
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  try {
    const { changed } = updateCommitAtlasImageVersions();
    console.log(changed ? "Updated CommitAtlas image versions." : "CommitAtlas image versions are current.");
  } catch (error) {
    console.error(error.message);
    process.exitCode = 1;
  }
}
